#!/usr/bin/env node
/**
 * Generate the TypeScript mirrors of the onboarding Core ↔ Shell wire types.
 *
 * The Rust enums in `rust/crates/vela-core/src/app/` are the source of truth;
 * `ts-rs` emits one `.ts` file per type into
 * `src/services/onboarding-core/generated/`. The output is committed, because
 * metro must be able to typecheck a fresh checkout without a Rust toolchain.
 *
 * Usage:
 *   node rust/scripts/gen-onboarding-types.mjs           write the generated files
 *   node rust/scripts/gen-onboarding-types.mjs --check   verify the committed
 *                                                        files are current (CI);
 *                                                        non-zero on drift
 *
 * `--check` generates into a temporary directory and compares byte-for-byte, so
 * it never leaves a half-written state behind on failure. Unlike the wasm
 * artifact, this output IS reproducible across machines: it is text derived from
 * text this repo controls.
 */

import { execFileSync } from 'node:child_process';
import { mkdtempSync, readdirSync, readFileSync, rmSync, mkdirSync, writeFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const RUST_DIR = dirname(dirname(fileURLToPath(import.meta.url)));
const REPO_ROOT = dirname(RUST_DIR);
const OUT_DIR = join(REPO_ROOT, 'src', 'services', 'onboarding-core', 'generated');

const CHECK_ONLY = process.argv.includes('--check');

function generateInto(target) {
  execFileSync(
    'cargo',
    [
      'run',
      '--quiet',
      '--manifest-path',
      join(RUST_DIR, 'Cargo.toml'),
      '-p',
      'vela-core',
      '--features',
      'bindings',
      '--bin',
      'generate_onboarding_bindings',
      '--',
      target,
    ],
    { cwd: RUST_DIR, stdio: ['ignore', 'ignore', 'inherit'] },
  );
}

function readDir(dir) {
  if (!existsSync(dir)) return {};
  return Object.fromEntries(
    readdirSync(dir)
      .filter((name) => name.endsWith('.ts'))
      .sort()
      .map((name) => [name, readFileSync(join(dir, name), 'utf8')]),
  );
}

/** A barrel so call sites import from one path instead of a dozen. */
function writeIndex(dir) {
  const types = readdirSync(dir)
    .filter((name) => name.endsWith('.ts') && name !== 'index.ts')
    .sort();
  writeFileSync(
    join(dir, 'index.ts'),
    '// @generated by rust/scripts/gen-onboarding-types.mjs — do not edit.\n' +
      types.map((name) => `export * from './${name.replace(/\.ts$/, '')}';`).join('\n') +
      '\n',
  );
}

if (CHECK_ONLY) {
  const staging = mkdtempSync(join(tmpdir(), 'vela-onboarding-types-'));
  try {
    generateInto(staging);
    writeIndex(staging); // the barrel is part of the output, so it is part of the check
    const fresh = readDir(staging);
    const committed = readDir(OUT_DIR);

    const missing = Object.keys(fresh).filter((name) => !(name in committed));
    const extra = Object.keys(committed).filter((name) => !(name in fresh));
    const changed = Object.keys(fresh).filter(
      (name) => name in committed && committed[name] !== fresh[name],
    );

    if (missing.length || extra.length || changed.length) {
      const detail = [
        ...missing.map((n) => `  ${n}: missing from the committed output`),
        ...extra.map((n) => `  ${n}: committed but no longer generated`),
        ...changed.map((n) => `  ${n}: differs from a fresh generation`),
      ].join('\n');
      console.error(
        'gen-onboarding-types --check: the committed TypeScript does not match the Rust wire types.\n' +
          detail +
          '\n\nRun `npm run gen:onboarding-types` and commit the result.',
      );
      process.exit(1);
    }
    console.log(
      `gen-onboarding-types --check: ${Object.keys(fresh).length} generated types are current`,
    );
  } finally {
    rmSync(staging, { recursive: true, force: true });
  }
} else {
  mkdirSync(OUT_DIR, { recursive: true });
  // Remove stale files first: a renamed Rust type would otherwise leave its old
  // mirror behind, and a stale mirror still typechecks.
  for (const name of readdirSync(OUT_DIR).filter((n) => n.endsWith('.ts'))) {
    rmSync(join(OUT_DIR, name));
  }
  generateInto(OUT_DIR);
  writeIndex(OUT_DIR);
  const written = readdirSync(OUT_DIR).filter((n) => n.endsWith('.ts'));
  console.log(`gen-onboarding-types: wrote ${written.length} files to ${OUT_DIR}`);
}
